    b.buffer = (unsigned char*)std::malloc(256); b.buffer[0] = 0; b.ptr = b.buffer; b.storage = 256; b.endbyte = 0; b.endbit = 0;
    writeB(&b, 0x5, 3);            /* 101 */
    writeB(&b, 0xF1, 1);           /* only the low bit (1) */
    writeB(&b, 0xABCD, 16);
